function openUpdates(){page='Settings';nav();render()}function nav(){let n=$('#nav');n.innerHTML=NAV.map(x=>`<button data-page="${x}" class="${x===page?'active':''}">${x}</button>`).join('');$$('button',n).forEach(b=>b.onclick=()=>{let target=b.dataset.page;if(target==='Deep Research'&&page==='Deep Research'&&researchDetailActive){returnFromResearch();return}++researchRequestSeq;if(target==='Deep Research')researchDetailActive=false;page=target;nav();render()})}
