const OVERLAY_LABELS={volume:'Volume',sma20:'SMA20',sma50:'SMA50',sma200:'SMA200',support:'Support',resistance:'Resistance',entry:'Entry Zone',risk:'Risk Exit',target:'Take Profit',events:'Events'};
function formatChartMoment(v){if(!v)return'—';try{let d=new Date(v);let opts={year:'numeric',month:'short',day:'numeric'};if(String(v).includes('T'))opts={...opts,hour:'numeric',minute:'2-digit'};return d.toLocaleString([],opts)}catch{return String(v)}}
