function chartInner(hist=[],levels={}){let d=hist.filter(x=>x.close!=null);if(d.length<2)return'<div class="empty">No chart data</div>';let vals=d.map(x=>Number(x.close));let extra=[];let ind=levels.indicators||{},pm=levels.price_model||{};if(chartOverlayState.sma20&&ind.sma20)extra.push(ind.sma20);if(chartOverlayState.sma50&&ind.sma50)extra.push(ind.sma50);if(chartOverlayState.sma200&&ind.sma200)extra.push(ind.sma200);if(chartOverlayState.support&&pm.nearest_support)extra.push(pm.nearest_support);if(chartOverlayState.resistance&&pm.first_resistance)extra.push(pm.first_resistance);if(chartOverlayState.risk&&pm.risk_exit)extra.push(pm.risk_exit);if(chartOverlayState.target&&pm.take_profit_zone)extra.push(...pm.take_profit_zone);if(chartOverlayState.entry&&pm.buy_zone)extra.push(...pm.buy_zone);let all=[...vals,...extra.filter(Number.isFinite)];let mn=Math.min(...all),mx=Math.max(...all),pad=(mx-mn||1)*.08;mn-=pad;mx+=pad;let rg=mx-mn||1;let y=v=>220-((v-mn)/rg)*195;let pts=vals.map((v,i)=>`${(i/(vals.length-1))*1000},${y(v)}`).join(' ');let maxVol=Math.max(1,...d.map(x=>Number(x.volume||0)));let bars=chartOverlayState.volume?d.map((x,i)=>{let h=(Number(x.volume||0)/maxVol)*46;let x0=(i/(d.length))*1000;let w=Math.max(1,1000/d.length*.72);return `<rect x="${x0}" y="${292-h}" width="${w}" height="${h}" class="volume-bar"/>`}).join(''):'';let refs=[];function line(value,kind,label){if(value==null||!Number.isFinite(Number(value)))return;let yy=y(Number(value));if(yy<4||yy>222)return;refs.push(`<line x1="0" y1="${yy}" x2="1000" y2="${yy}" class="ref-line ${kind}"/><text x="8" y="${Math.max(10,yy-4)}" class="ref-label ${kind}">${label} ${money(value)}</text>`)}if(chartOverlayState.entry&&pm.buy_zone?.length===2){let a=y(pm.buy_zone[0]),b=y(pm.buy_zone[1]),top=Math.min(a,b),h=Math.abs(a-b);refs.push(`<rect x="0" y="${top}" width="1000" height="${Math.max(2,h)}" class="entry-zone"/><text x="8" y="${Math.max(12,top+12)}" class="ref-label entry">ENTRY ZONE</text>`)}if(chartOverlayState.sma20)line(ind.sma20,'sma20','SMA20');if(chartOverlayState.sma50)line(ind.sma50,'sma50','SMA50');if(chartOverlayState.sma200)line(ind.sma200,'sma200','SMA200');if(chartOverlayState.support)line(pm.nearest_support,'support','SUPPORT');if(chartOverlayState.resistance)line(pm.first_resistance,'resistance','RESISTANCE');if(chartOverlayState.risk)line(pm.risk_exit,'risk','RISK EXIT');if(chartOverlayState.target&&pm.take_profit_zone?.[0])line(pm.take_profit_zone[0],'target','TAKE PROFIT');if(chartOverlayState.events){for(let i=1;i<d.length;i++){let op=Number(d[i].open),prev=Number(d[i-1].close);if(op&&prev){let gp=(op/prev-1)*100;if(Math.abs(gp)>=4){let xx=(i/(d.length-1))*1000;refs.push(`<line x1="${xx}" y1="12" x2="${xx}" y2="220" class="event-line gap"/><text x="${Math.min(940,xx+5)}" y="24" class="event-label">GAP ${gp>=0?'+':''}${gp.toFixed(1)}%</text>`)}}}let news=(levels.news||[]).filter(n=>n.impact==='HIGH'&&n.published).slice(0,5);for(let n of news){let nd=new Date(n.published);if(Number.isNaN(nd.getTime()))continue;let target=nd.toISOString().slice(0,10),idx=d.findIndex(x=>String(x.date||x.time||'').slice(0,10)===target);if(idx<0)continue;let xx=(idx/(d.length-1))*1000;refs.push(`<circle cx="${xx}" cy="34" r="5" class="event-dot"><title>${esc(n.event_type||'NEWS')}: ${esc(n.title||'')}</title></circle>`)}}return `<div class="chart-wrap" data-min="${mn}" data-max="${mx}"><svg class="chart smart-chart" viewBox="0 0 1000 300" preserveAspectRatio="none"><g class="volume-layer">${bars}</g><g class="reference-layer">${refs.join('')}</g><polyline points="${pts}" fill="none" stroke="currentColor" stroke-width="3" vector-effect="non-scaling-stroke"/></svg><div class="chart-crosshair" hidden></div><div class="chart-crosshair-dot" hidden></div><div class="chart-tooltip" hidden><b>—</b><span>—</span></div></div><div class="chart-hover-meta"><div><span>Hover Price</span><b class="js-chart-price">—</b></div><div><span>Time / Date</span><b class="js-chart-time">—</b></div><div><span>Volume</span><b class="js-chart-volume">—</b></div><div><span>Points</span><b>${d.length}</b></div></div>`}
function interactiveChartShell(hist=[],active='1y',levels={}){return `<div class="chart-panel"><div class="chart-toolbar"><div><div class="caption">Interactive price history</div><div class="tiny">Hover for exact price/time. Overlay lines are current research reference levels.</div></div>${chartToolbar(active)}</div>${overlayToolbar()}${chartInner(hist,levels)}</div>`}
function mountPriceHistory(container,ticker,hist=[],active='1y',levels={}){if(!container)return;let chartSeq=(chartRequestVersions.get(container)||0)+1;chartRequestVersions.set(container,chartSeq);container.innerHTML=interactiveChartShell(hist,active,levels);let wrap=container.querySelector('.chart-wrap'),tooltip=container.querySelector('.chart-tooltip'),cross=container.querySelector('.chart-crosshair'),dot=container.querySelector('.chart-crosshair-dot'),priceEl=container.querySelector('.js-chart-price'),timeEl=container.querySelector('.js-chart-time'),volEl=container.querySelector('.js-chart-volume');let data=(hist||[]).filter(x=>x.close!=null),mn=Number(wrap?.dataset.min||0),mx=Number(wrap?.dataset.max||1),rg=mx-mn||1;function showAt(clientX){if(!wrap||!data.length)return;let rect=wrap.getBoundingClientRect(),ratio=Math.max(0,Math.min(1,(clientX-rect.left)/rect.width)),idx=Math.max(0,Math.min(data.length-1,Math.round(ratio*(data.length-1)))),point=data[idx],leftRatio=data.length>1?idx/(data.length-1):0,leftPx=leftRatio*rect.width,price=money(point.close),when=formatChartMoment(point.time||point.date),yView=220-((Number(point.close)-mn)/rg)*195,yPx=yView/300*rect.height;priceEl.textContent=price;timeEl.textContent=when;volEl.textContent=point.volume?number(point.volume,true):'—';tooltip.hidden=false;cross.hidden=false;dot.hidden=false;tooltip.querySelector('b').textContent=price;tooltip.querySelector('span').textContent=when;cross.style.left=`${leftPx}px`;dot.style.left=`${leftPx}px`;dot.style.top=`${yPx}px`;let tipWidth=190,desired=Math.min(Math.max(8,leftPx+12),Math.max(8,rect.width-tipWidth-8));tooltip.style.left=`${desired}px`;tooltip.style.top='10px'}if(wrap){wrap.addEventListener('mousemove',e=>showAt(e.clientX));wrap.addEventListener('mouseenter',e=>showAt(e.clientX));wrap.addEventListener('mouseleave',()=>{tooltip.hidden=true;cross.hidden=true;dot.hidden=true})}container.querySelectorAll('.range-btn').forEach(btn=>btn.onclick=async()=>{let range=btn.dataset.range;if(!range||range===active)return;container.classList.add('busy');container.querySelectorAll('.range-btn').forEach(b=>b.disabled=true);try{let out=await api('/api/chart/'+encodeURIComponent(ticker)+'?range='+encodeURIComponent(range));if(!container.isConnected||chartRequestVersions.get(container)!==chartSeq)return;researchChartRange=range;mountPriceHistory(container,ticker,out.history||out.rows||[],range,levels)}catch(e){if(!container.isConnected||chartRequestVersions.get(container)!==chartSeq)return;container.classList.remove('busy');container.insertAdjacentHTML('afterbegin',errorBox(e));container.querySelectorAll('.range-btn').forEach(b=>b.disabled=false)}});container.querySelectorAll('.overlay-btn').forEach(btn=>btn.onclick=()=>{let key=btn.dataset.overlay;chartOverlayState[key]=!chartOverlayState[key];mountPriceHistory(container,ticker,data,active,levels)})}
