async function Market(){setTitle('Market','Major indexes, sector rotation and current market headlines');let v=$('#view'),viewSeq=renderGeneration,marketSeq=++marketRequestSeq;v.innerHTML=loading('Loading market overview…');try{let d=await api('/api/dashboard');if(!viewActive(viewSeq)||marketSeq!==marketRequestSeq)return;let maxSector=Math.max(1,...d.sectors.map(x=>Math.abs(x.change_percent||0)));v.innerHTML=`<div class="section-head"><div><h2>Market Overview</h2><p>Free best-effort data · updated ${timeText(d.updated_at)}</p></div><div class="toolbar"><button class="secondary" id="refreshDash">REFRESH</button><button class="primary" id="quickHunter">RUN HUNTER</button></div></div>${(d.errors||[]).length?`<div class="warning-box">Partial market data: ${d.errors.length} feed(s) unavailable. Missing quotes or headlines are omitted; verify the market regime before relying on it.</div>`:''}<div class="regime-banner"><div><span class="caption">MARKET REGIME</span><b>${esc(d.regime?.label||'UNKNOWN')}</b><span class="tiny">S&P 1M ${d.regime?.sp500_momentum_1m!=null?(d.regime.sp500_momentum_1m>=0?'+':'')+d.regime.sp500_momentum_1m+'%':'—'} · VIX ${d.regime?.vix??'—'}</span></div><span class="status ${statusClass(d.regime?.label||'')}">ENTRY ADJ ${d.regime?.entry_adjust??0}</span></div><div class="market-indexes">${d.indexes.map(x=>`<div class="index-card"><span class="symbol">${esc(x.ticker)}</span><div class="name">${esc(x.name)}</div><div class="value">${money(x.price)}</div><div>${pct(x.change_percent)}</div></div>`).join('')}</div><div class="grid2"><div class="stack">${panel('Sector Rotation',`<div class="sector-table">${d.sectors.map(x=>`<div class="sector-row"><div><div>${esc(x.name)}</div><div class="bar"><div class="fill" style="width:${Math.min(100,Math.abs(x.change_percent||0)/maxSector*100)}%"></div></div></div><b>${esc(x.ticker)}</b><span>${pct(x.change_percent)}</span></div>`).join('')}</div>`)}${panel('What the terminal does',`<div class="fund-grid">${fundCard('Discovery','Quantitative Hunter')}${fundCard('Verification','SEC + source scoring')}${fundCard('Defense','Exit-risk monitoring')}${fundCard('AI','Optional Ollama')}</div><p class="tiny" style="margin-top:10px">The core engine never requires Ollama and does not treat headlines as verified facts by default.</p>`)} </div>${panel('Market News Intelligence',newsRows(d.news),`<span class="caption">${d.news.length} headlines</span>`)}</div>`;$('#refreshDash').onclick=()=>Market();$('#quickHunter').onclick=()=>{page='Stonk Hunter';nav();render(true)}}catch(e){if(viewActive(viewSeq)&&marketSeq===marketRequestSeq)v.innerHTML=errorBox(e)}}

function searchBar(button='ANALYZE',value='NVDA'){return`<form class="searchbar" id="search"><input id="ticker" value="${esc(value)}" placeholder="Ticker, e.g. NVDA"><button class="primary">${button}</button></form>`}
function stockHero(d){let q=d.quote||{},ex=d.exit_risk||{},riskCls=ex.score>=70?'danger':ex.score>=30?'watch':'';return`<section class="panel hero-stock"><div><div class="stock-id"><h2>${esc(q.ticker)}</h2><span>${esc(q.name)}</span></div><div class="stock-price">${money(q.price)} <small>${pct(q.change_percent)}</small></div><div class="stock-meta">${esc(q.exchange||'Exchange unavailable')} · ${esc(q.currency||'USD')} · Updated ${timeText(q.updated_at)}</div></div><div class="exit-badge ${riskCls}"><small>EXIT RISK</small><b>${ex.score??'—'}</b><span>${esc(ex.label||'NORMAL')}</span></div></section>${q.stale?`<div class="warning-box">STALE PRICE: Latest observed bar was ${timeText(q.updated_at)}. Current entry and exit decisions are unavailable until market data refreshes.</div>`:''}`}
function stockMetrics(d){let q=d.quote||{},i=d.indicators||{},p=d.price_model||{},e=d.earnings||{};return`<div class="metric-strip">${metricCard('Day Range',`${money(q.day_low)} – ${money(q.day_high)}`)}${metricCard('52W Range',`${money(q.fifty_two_low)} – ${money(q.fifty_two_high)}`)}${metricCard('RSI 14',i.rsi14!=null?i.rsi14.toFixed(1):'—')}${metricCard('Timing Risk',(p.overextension_risk??safenum(d.scores?.timing_risk))+'/100',esc(p.timing_status||''))}${metricCard('Gap Risk',(i.gap_risk??0)+'/100',i.current_gap_pct!=null?`${i.current_gap_pct>=0?'+':''}${i.current_gap_pct.toFixed(1)}% latest gap`:'')}${metricCard('Knife Risk',(i.falling_knife_risk??0)+'/100',`Stabilization ${i.stabilization_score??'—'}/100`)}${metricCard('Earnings',e.available?(e.days_to_earnings>=0?`${e.days_to_earnings}d`:'Passed'):'Unknown',esc(e.risk||'UNKNOWN'))}${metricCard('Room to Resistance',i.room_to_resistance_pct!=null?pct(i.room_to_resistance_pct,1):'—')}</div>`}
function safenum(v){return v==null?'—':Math.round(Number(v))}
function researchPanels(d,showResearch=true){let i=d.indicators||{},p=d.price_model||{},s=d.scores||{},dr=d.score_explanations||{};let timingCls=(p.overextension_risk??0)>=65?'danger':(p.overextension_risk??0)>=45?'warn':'high';let zones=`<div class="research-status"><span class="status ${timingCls}">${esc(p.timing_status||'NEUTRAL')}</span><span class="tiny">Timing risk ${p.overextension_risk??'—'}/100 · Pullback quality ${p.pullback_quality??'—'}/100</span></div><div class="price-zones"><div class="zone"><span>Deep Pullback</span><b>${rangeText(p.strong_buy_zone)}</b></div><div class="zone"><span>Preferred Entry</span><b>${rangeText(p.buy_zone)}</b></div><div class="zone"><span>First Target</span><b>${rangeText(p.take_profit_zone)}</b></div><div class="zone"><span>Risk Exit</span><b>${money(p.risk_exit)}</b></div></div><div class="scenario-row"><div class="scenario"><span>Nearest Support</span><b>${money(p.nearest_support)}</b></div><div class="scenario"><span>First Resistance</span><b>${money(p.first_resistance)}</b></div><div class="scenario"><span>Upside / Downside</span><b>${p.upside_downside_ratio??'—'} : 1</b></div></div><div class="fund-grid" style="margin-top:8px">${fundCard('R/R to Risk Exit',p.risk_reward!=null?p.risk_reward+':1':'—')}${fundCard('Upside to Resistance',p.potential_upside_pct!=null?pct(p.potential_upside_pct,1):'—')}${fundCard('Downside to Support',p.downside_to_support_pct!=null?`${p.downside_to_support_pct.toFixed(1)}%`:'—')}${fundCard('Gap Risk',(p.gap_risk??0)+'/100')}${fundCard('Knife Risk',(p.falling_knife_risk??0)+'/100')}${fundCard('Timing Risk',(p.overextension_risk??'—')+'/100')}</div><p class="tiny" style="margin-top:8px">${esc(p.method||'')} · ${esc(p.warning||'')}</p>`;let scoresHtml=`<div class="score-list">${scoreRow('Opportunity',s.opportunity,false,dr.opportunity)}${scoreRow('Entry',s.entry,false,dr.entry)}${scoreRow('Quality',s.quality,false,dr.quality)}${scoreRow('Momentum',s.momentum,false,dr.momentum)}${scoreRow('Risk',s.risk,true,dr.risk)}${scoreRow('Confidence',s.confidence,false,dr.confidence)}</div>`;let technical=`<div class="fund-grid">${fundCard('SMA 20',money(i.sma20))}${fundCard('SMA 50',money(i.sma50))}${fundCard('SMA 200',money(i.sma200))}${fundCard('ATR 14',money(i.atr14))}${fundCard('1W Momentum',i.momentum_1w!=null?pct(i.momentum_1w,1):'—')}${fundCard('1M Momentum',i.momentum_1m!=null?pct(i.momentum_1m,1):'—')}${fundCard('3M Momentum',i.momentum_3m!=null?pct(i.momentum_3m,1):'—')}${fundCard('20D Volatility',i.volatility20!=null?i.volatility20.toFixed(1)+'%':'—')}${fundCard('Latest Gap',i.current_gap_pct!=null?pct(i.current_gap_pct,1):'—')}${fundCard('Lower Lows 10D',i.lower_lows_10d??'—')}${fundCard('Days Since 20D Low',i.days_since_20d_low??'—')}${fundCard('Stabilization',(i.stabilization_score??'—')+'/100')}</div>`;return`<div class="grid2">${panel('Price History',miniChart(d.history,d.ticker||d.quote?.ticker||lastResearchTicker,researchChartRange),'<span class="caption">Hover + selectable range</span>')}${panel('Decision Scores',scoresHtml,'<span class="badge">CALCULATED</span>')}</div><div class="grid2" style="margin-top:12px">${panel('Entry Discipline / Exit Analysis',zones,'<span class="badge">DOWNSIDE FIRST</span>')}${panel('Technical Evidence',technical,'<span class="badge">CALCULATED</span>')}</div>`}

function hunterValue(r,key){if(key==='ticker')return r.ticker;if(key==='price')return r.price;if(key==='change')return r.change_percent;if(key==='opportunity')return r.scores?.opportunity;if(key==='entry')return r.scores?.entry;if(key==='quality')return r.scores?.quality;if(key==='momentum')return r.scores?.momentum;if(key==='risk')return r.scores?.risk;if(key==='confidence')return r.scores?.confidence;if(key==='volume')return r.indicators?.avg_volume20;if(key==='rr')return r.price_model?.risk_reward;if(key==='setup_rank')return r.setup_rank;if(key==='sector')return r.sector?.sector||'';return 0}
function filteredHunter(){if(!hunterData)return[];let a=[...(hunterData.results||[])];if(hunterFilter==='Momentum')a=a.filter(x=>x.scores.momentum>=70);if(hunterFilter==='Quality')a=a.filter(x=>x.scores.quality>=65);if(hunterFilter==='Low Risk')a=a.filter(x=>x.scores.risk<40);if(hunterFilter==='Strong Setup')a=a.filter(x=>x.status==='STRONG SETUP');if(hunterFilter==='Pullback Watch')a=a.filter(x=>x.status==='WAIT FOR PULLBACK');if(hunterFilter==='Oversold')a=a.filter(x=>(x.indicators.rsi14??100)<40&&(x.indicators.falling_knife_risk??100)<55);if(hunterFilter==='High Volume')a=a.filter(x=>(x.indicators.relative_volume??0)>=1.5);if(hunterSearch)a=a.filter(x=>(x.ticker+' '+(x.name||'')).toLowerCase().includes(hunterSearch.toLowerCase()));a=a.filter(x=>(x.scores.opportunity??0)>=hunterMinOpportunity&&(x.scores.risk??100)<=hunterMaxRisk);if(hunterSector!=='All')a=a.filter(x=>(x.sector?.sector||'Broad Market')===hunterSector);let dir=hunterSort.dir==='asc'?1:-1,key=hunterSort.key;a.sort((x,y)=>{let A=hunterValue(x,key),B=hunterValue(y,key);if(typeof A==='string')return A.localeCompare(B)*dir;return ((Number(A)||0)-(Number(B)||0))*dir});return a}
function sortHead(label,key){let arrow=hunterSort.key===key?(hunterSort.dir==='asc'?' ▲':' ▼'):'';return`<th data-sort="${key}" class="sortable">${label}${arrow}</th>`}
function renderHunterTable(){let out=$('#hunterResults');if(!out||!hunterData)return;let rows=filteredHunter(),sectors=['All',...new Set((hunterData.results||[]).map(x=>x.sector?.sector||'Broad Market'))];out.innerHTML=`<div class="hunter-controls"><div class="filterbar">${['All','Momentum','Quality','Low Risk','Strong Setup','Pullback Watch','Oversold','High Volume'].map(x=>`<button data-f="${x}" class="${hunterFilter===x?'active':''}">${x}</button>`).join('')}</div><div class="hunter-fields"><input id="hunterSearch" placeholder="Filter ticker/company" value="${esc(hunterSearch)}"><label>Min Opp <input id="hunterMinOpp" type="number" min="0" max="100" value="${hunterMinOpportunity}"></label><label>Max Risk <input id="hunterMaxRisk" type="number" min="0" max="100" value="${hunterMaxRisk}"></label><select id="hunterSector">${sectors.map(x=>`<option ${x===hunterSector?'selected':''}>${esc(x)}</option>`).join('')}</select></div></div><div class="table-wrap"><table><thead><tr>${sortHead('Stock','ticker')}${sortHead('Sector','sector')}${sortHead('Price','price')}${sortHead('Day','change')}${sortHead('Opportunity','opportunity')}${sortHead('Entry','entry')}${sortHead('Quality','quality')}${sortHead('Momentum','momentum')}${sortHead('Risk','risk')}${sortHead('Confidence','confidence')}${sortHead('Avg Vol','volume')}<th>Gap</th><th>Knife</th>${sortHead('R/R','rr')}<th>Status</th><th>Why</th></tr></thead><tbody>${rows.map(r=>`<tr data-ticker="${r.ticker}"><td><b>${r.ticker}</b><span class="company">${esc(r.name)}</span></td><td>${esc(r.sector?.sector||'Broad Market')}</td><td>${money(r.price)}</td><td>${pct(r.change_percent)}</td><td><span class="score-chip">${r.scores.opportunity}</span></td><td>${r.scores.entry}</td><td>${r.scores.quality}</td><td>${r.scores.momentum}</td><td><span class="score-chip risk">${r.scores.risk}</span></td><td>${r.scores.confidence}</td><td>${number(r.indicators.avg_volume20,true)}</td><td><span class="${clsRisk(r.indicators.gap_risk||0)}">${r.indicators.gap_risk??0}</span></td><td><span class="${clsRisk(r.indicators.falling_knife_risk||0)}">${r.indicators.falling_knife_risk??0}</span></td><td>${r.price_model.risk_reward??'—'}</td><td><span class="status ${statusClass(r.status)}">${esc(r.status)}</span></td><td><span class="company">${esc(r.why||'')}</span></td></tr>`).join('')}</tbody></table></div><p class="tiny" style="margin-top:8px">Showing ${rows.length} of ${hunterData.results.length} results · ${hunterData.note}</p>`;$$('.filterbar button').forEach(b=>b.onclick=()=>{hunterFilter=b.dataset.f;renderHunterTable()});$$('[data-sort]',out).forEach(h=>h.onclick=()=>{let k=h.dataset.sort;if(hunterSort.key===k)hunterSort.dir=hunterSort.dir==='asc'?'desc':'asc';else hunterSort={key:k,dir:k==='ticker'||k==='sector'?'asc':'desc'};renderHunterTable()});$('#hunterSearch').onchange=e=>{hunterSearch=e.target.value;renderHunterTable()};$('#hunterMinOpp').onchange=e=>{hunterMinOpportunity=Math.max(0,Math.min(100,Number(e.target.value)||0));renderHunterTable()};$('#hunterMaxRisk').onchange=e=>{hunterMaxRisk=Math.max(0,Math.min(100,Number(e.target.value)||100));renderHunterTable()};$('#hunterSector').onchange=e=>{hunterSector=e.target.value;renderHunterTable()};$$('tbody tr',out).forEach(tr=>{tr.title='Open Deep Research';tr.onclick=e=>{if(e.target.closest('input,button,select'))return;openResearchTicker(tr.dataset.ticker,'Stonk Hunter')}})}
async function Hunter(auto=false){setTitle('Stonk Hunter','Sortable, filterable discovery with chase and falling-knife protection');let v=$('#view'),viewSeq=renderGeneration,hunterSeq=0;v.innerHTML=`<div class="section-head"><div><h2>Opportunity Scanner</h2><p>Fast first pass. Top finalists are prefetched in the background so Deep Research opens faster.</p></div><div class="toolbar"><button class="primary" id="runHunter">RUN HUNTER</button></div></div><div id="hunterStats"></div><div id="hunterResults">${hunterData?loading('Rendering cached scan…'):'<div class="empty">Run Hunter to scan the configured stock universe.</div>'}</div>`;async function run(){let seq=++hunterSeq;let b=$('#runHunter');b.disabled=true;$('#hunterResults').innerHTML=loading('Scanning entry quality, gaps, falling-knife risk, trend and market regime…');try{let scanned=await api('/api/hunter',{method:'POST',body:'{}'});if(!viewActive(viewSeq)||seq!==hunterSeq)return;hunterData=scanned;$('#hunterStats').innerHTML=`<div class="kpi-row" style="margin-bottom:10px">${metricCard('Scanned',hunterData.scanned)}${metricCard('Returned',hunterData.results.length)}${metricCard('Unavailable',Math.max(0,hunterData.scanned-(hunterData.successful??hunterData.results.length)),'Provider failures or stale prices')}${metricCard('Market Regime',esc(hunterData.regime?.label||'UNKNOWN'),`Entry adj ${hunterData.regime?.entry_adjust??0}`)}${metricCard('Updated',new Date(hunterData.updated_at).toLocaleTimeString())}</div>`;renderHunterTable()}catch(e){if(viewActive(viewSeq)&&seq===hunterSeq)$('#hunterResults').innerHTML=errorBox(e)}finally{b.disabled=false}}$('#runHunter').onclick=run;if(hunterData)renderHunterTable();if(auto)run()}

function researchLists(title,items=[]){return`<div class="list-box"><h4>${title}</h4>${items?.length?`<ul class="thesis-list">${items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<div class="tiny">No items reported.</div>'}</div>`}
function decisionOverview(d){let x=d.decision_layer||{},r=x.market_regime||{},rs=x.relative_strength||{},e=x.earnings||d.earnings||{},pm=d.price_model||{};return `<div class="decision-duo"><div class="decision-card"><span>COMPANY QUALITY</span><b>${x.company_quality??d.scores?.quality??'—'}</b><strong class="${(x.company_quality??0)>=62?'good':(x.company_quality??0)<45?'bad':'warn'}">${esc(x.company_label||'MIXED')}</strong><small>Business/fundamental quality — separate from today's price.</small></div><div class="decision-card"><span>CURRENT ENTRY</span><b>${x.entry_quality??d.scores?.entry??'—'}</b><strong class="${(x.entry_quality??0)>=70?'good':(x.entry_quality??0)<45?'bad':'warn'}">${esc(x.entry_label||'WAIT')}</strong><small>Downside, gap/knife risk, event risk and R/R at the current price.</small></div><div class="decision-card compact"><span>MARKET REGIME</span><b class="regime-text">${esc(r.label||'UNKNOWN')}</b><small>S&P 1M ${r.sp500_momentum_1m!=null?(r.sp500_momentum_1m>=0?'+':'')+r.sp500_momentum_1m+'%':'—'} · VIX ${r.vix??'—'}</small></div><div class="decision-card compact"><span>RELATIVE STRENGTH</span><b>${rs.score??'—'}</b><strong>${esc(rs.label||'UNKNOWN')}</strong><small>vs ${esc(rs.benchmark_name||rs.benchmark||'market')}</small></div><div class="decision-card compact"><span>EARNINGS RISK</span><b>${e.available?(e.days_to_earnings>=0?e.days_to_earnings+'d':'Passed'):'UNKNOWN'}</b><strong class="${e.risk==='IMMINENT'?'bad':e.risk==='NEAR'?'warn':'good'}">${esc(e.risk||'UNKNOWN')}</strong><small>Best-effort calendar; unavailable data is shown as unknown.</small></div><div class="decision-card compact"><span>DOWNSIDE FIRST</span><b>${pm.upside_downside_ratio??'—'} : 1</b><strong class="${(pm.upside_downside_ratio??0)>=1.5?'good':(pm.upside_downside_ratio??0)<1?'bad':'warn'}">${(pm.upside_downside_ratio??0)>=1.5?'FAVORABLE':(pm.upside_downside_ratio??0)<1?'WEAK':'MIXED'}</strong><small>${pm.downside_to_support_pct??'—'}% downside to support vs ${pm.potential_upside_pct??'—'}% room to resistance.</small></div></div><div class="grid3" style="margin-top:10px">${researchLists('Why NOT buy now',x.why_not_buy)}${researchLists('Would improve the decision',x.upgrade_conditions)}${researchLists('Would weaken / invalidate',x.downgrade_conditions)}</div>`}
function thesisHealthPanel(d){let th=d.thesis_health||{};if(!th.tracked)return `<div class="empty compact-empty">No structured thesis is tracked for this ticker. Add the position in Portfolio and select the reasons you bought it.</div>`;return `<div class="thesis-health-head"><div><span class="caption">THESIS HEALTH</span><b class="${(th.score??0)>=70?'good':(th.score??0)<45?'bad':'warn'}">${th.score??'—'}/100</b></div><div class="tiny">${th.valid} valid · ${th.invalid} broken · ${th.unknown} unknown</div></div><div class="thesis-checks">${(th.items||[]).map(x=>`<div class="thesis-check ${x.valid===true?'ok':x.valid===false?'broken':'unknown'}"><span>${x.valid===true?'✓':x.valid===false?'✕':'?'}</span><div><b>${esc(x.label)}</b><small>${esc(x.detail)}</small></div></div>`).join('')}</div>`}
function researchHistoryPanel(d){let h=d.research_history||[],chg=d.research_change||{};if(!h.length)return '<div class="empty compact-empty">No previous decision snapshots yet.</div>';let delta=chg.available?`<div class="change-summary"><b>WHAT CHANGED</b><small>${esc(chg.summary||'')}</small><div>${(chg.items||[]).map(x=>`<span class="change-chip ${x.delta>0?'up':'down'}">${esc(x.metric)} ${x.delta>0?'+':''}${x.delta}</span>`).join('')}</div></div>`:'';return delta+`<div class="history-list">${h.map((x,i)=>`<div class="history-row"><div><b>${esc(x.status||'UNKNOWN')}</b><small>${timeText(x.created_at)}</small></div><span>${money(x.price)}</span><span>Opp ${x.opportunity??'—'}</span><span>Entry ${x.entry??'—'}</span><span>Risk ${x.risk??'—'}</span>${i===0?'<em>LATEST</em>':''}</div>`).join('')}</div>`}
function newsEventPanel(d){if(d.news_risk?.available===false)return '<div class="warning-box">News evidence unavailable. Risk impact is UNKNOWN until sources return reliable data.</div>';let ev=d.news_risk?.events||[];if(!ev.length)return '<div class="empty compact-empty">No material news events classified.</div>';return `<div class="event-list">${ev.slice(0,8).map(e=>`<div class="event-row"><div><b>${esc(e.type)}</b><small>${esc(e.title||'')}</small></div><span class="status ${e.confirmation?.includes('UNVERIFIED')?'warn':'high'}">${esc(e.confirmation)}</span><span>${e.outlet_count??0} outlets</span><span class="${(e.risk_points||0)>0?'bad':(e.risk_points||0)<0?'good':''}">${e.risk_points>0?'+':''}${e.risk_points}</span></div>`).join('')}</div>`}

function freshnessPanel(d){let f=d.freshness||{};return `<div class="freshness-grid">${fundCard('PRICE',timeText(f.market))}${fundCard('RESEARCH',timeText(f.research))}${fundCard('NEWS',timeText(f.news))}${fundCard('SEC FISCAL END',esc(f.sec_fiscal_end||'Unavailable'))}${fundCard('LATEST FILING',esc(f.latest_filing||'Unavailable'))}</div><p class="tiny" style="margin-top:8px">Missing or stale evidence reduces confidence instead of being guessed.</p>`}
async function DeepResearch(){setTitle('Deep Research','Reliability-first staged research with downside, event and evidence checks');let v=$('#view');
if(!researchDetailActive){v.innerHTML=`<div class="section-head"><div><h2>Deep Research</h2><p>Search a ticker here, or click a Hunter result. Stock details open as a reversible view.</p></div>${searchBar('DEEP RESEARCH',lastResearchTicker)}</div><div class="grid2"><section class="panel panel-pad"><div class="panel-title"><h3>Research a stock</h3><span class="badge good">CORE ENGINE READY</span></div><p class="tiny">Deep Research first checks market structure and entry timing, then adds SEC fundamentals, filings, and current news in parallel. Ollama remains optional and on-demand.</p><div class="fund-grid" style="margin-top:12px">${fundCard('Step 1','Timing / downside')}${fundCard('Step 2','SEC evidence')}${fundCard('Step 3','News risk')}${fundCard('Step 4','Core decision')}</div></section><section class="panel panel-pad"><div class="panel-title"><h3>Navigation</h3></div><p class="tiny">When a ticker is open, use <b>← RETURN</b> or click <b>Deep Research</b> in the sidebar again to go back. Hunter results remain cached, including your active filter.</p>${lastResearchTicker?`<button class="secondary" id="resumeResearch" style="margin-top:10px">RESEARCH ${esc(lastResearchTicker)} AGAIN</button>`:''}</section></div>`;$('#search').onsubmit=e=>{e.preventDefault();openResearchTicker($('#ticker').value,'Deep Research')};let resume=$('#resumeResearch');if(resume)resume.onclick=()=>openResearchTicker(lastResearchTicker,'Deep Research');return}
v.innerHTML=`<div class="section-head"><div><div class="toolbar" style="margin-bottom:7px"><button class="secondary" id="researchReturn">← RETURN</button><span class="caption">${researchReturnPage==='Deep Research'?'BACK TO DEEP RESEARCH':`BACK TO ${esc(researchReturnPage)}`}</span></div><h2>${esc(lastResearchTicker)} Evidence Package</h2><p>Market/timing risk renders first; SEC and news evidence are added in parallel.</p></div>${searchBar('DEEP RESEARCH',lastResearchTicker)}</div><div id="out"></div>`;
function renderFull(d){let f=d.fundamentals||{},c=d.core_research||{},a=d.ai_research||{},src=d.source_summary||{};let fundamentals=`<div class="fund-grid">${fundCard('Revenue',number(f.revenue,true))}${fundCard('Revenue Growth',f.revenue_growth_pct!=null?pct(f.revenue_growth_pct,1):'—')}${fundCard('Net Income',number(f.net_income,true))}${fundCard('NI Growth',f.net_income_growth_pct!=null?pct(f.net_income_growth_pct,1):'—')}${fundCard('Operating Cash Flow',number(f.operating_cashflow,true))}${fundCard('FCF Estimate',number(f.free_cashflow_est,true))}${fundCard('Cash',number(f.cash,true))}${fundCard('Liabilities',number(f.liabilities,true))}</div><p class="tiny" style="margin-top:8px">Source: ${esc(f.source||'SEC unavailable')} · Fiscal end: ${esc(f.latest_fiscal_end||'—')}</p>`;let core=`<div class="research-status"><span class="status ${statusClass(c.status)}">${esc(c.status||'UNKNOWN')}</span><b>${c.confidence??0}% evidence confidence</b></div><p class="tiny">${esc(c.summary||'')}</p><div class="grid3" style="margin-top:9px">${researchLists('Bull case',c.bull_case)}${researchLists('Bear case',c.bear_case)}${researchLists('Contradicting evidence',c.contradicting_evidence)}</div>`;let ai=`<div id="aiResearchBox"><div class="research-status"><span class="status ${statusClass(a.status)}">${esc(a.status||'OFF')}</span></div><p class="tiny">${esc(a.summary||'')}</p>${a.enabled?'<button class="secondary" id="runAiResearch" style="margin-top:9px">RUN OLLAMA ANALYSIS</button>':''}</div>`;let source=`<div class="fund-grid">${fundCard('SEC Facts',src.sec_available?'AVAILABLE':'UNAVAILABLE')}${fundCard('Primary Filings',src.primary_filings??0)}${fundCard('News Sources',src.news_sources??0)}${fundCard('Primary-Source Confirmed',`${src.confirmed_news_events??0}/${src.news_events??0}`)}</div>${d.stored_thesis?`<div class="list-box" style="margin-top:9px"><h4>Stored position thesis</h4><div class="tiny">${esc(d.stored_thesis)}</div></div>`:''}`;let filings=(d.filings||[]).length?`<div class="table-wrap"><table><thead><tr><th>Form</th><th>Date</th><th>Importance</th><th>Description</th></tr></thead><tbody>${d.filings.map(x=>`<tr><td><a href="${esc(x.url||'#')}" target="_blank" style="color:var(--text)"><b>${esc(x.form)}</b></a></td><td>${esc(x.date||'—')}</td><td><span class="status ${x.importance==='HIGH'?'warn':''}">${esc(x.importance||'')}</span></td><td>${esc(x.description||'')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No SEC filing metadata available.</div>';$('#out').innerHTML=stockHero(d)+stockMetrics(d)+panel('Decision Quality',decisionOverview(d),`<span class="caption">COMPANY ≠ ENTRY</span>`)+`<div style="margin-top:12px"></div>`+researchPanels(d,true)+`<div class="research-columns" style="margin-top:12px"><div class="stack">${panel('Core Research',core)}${panel('Thesis Health',thesisHealthPanel(d))}${panel('SEC Fundamentals',fundamentals,'<span class="badge">PRIMARY FACTS</span>')}${panel('SEC Filings',filings)}</div><div class="stack">${panel('Evidence Quality',source,'<span class="badge">FACTS + COVERAGE</span>')}${panel('Data Freshness',freshnessPanel(d))}${panel('News Events',newsEventPanel(d),`<span class="caption">Risk ${d.news_risk?.available===false?'UNAVAILABLE':(d.news_risk?.score??0)+'/100'}</span>`)}${panel('Optional Ollama Interpretation',ai,'<span class="badge">AI INTERPRETATION</span>')}${panel('Research History',researchHistoryPanel(d))}${panel('News Intelligence',newsRows((d.news||[]).slice(0,14)),`<span class="caption">${d.news?.length??0} headlines</span>`)}</div></div>`;mountPriceHistory($('#out .price-history-slot'),d.ticker||d.quote?.ticker||lastResearchTicker,d.history||[],researchChartRange,{indicators:d.indicators||{},price_model:d.price_model||{},news:d.news||[],earnings:d.earnings||{}});let aiBtn=$('#runAiResearch');if(aiBtn)aiBtn.onclick=async()=>{let aiBox=$('#aiResearchBox');aiBtn.disabled=true;aiBtn.textContent='ANALYZING…';try{let x=await api('/api/ai-research/'+encodeURIComponent(d.ticker),{method:'POST'});if(!aiBox.isConnected)return;aiBox.innerHTML=`<div class="research-status"><span class="status ${statusClass(x.status)}">${esc(x.status||'AI')}</span>${x.model?`<span class="badge">${esc(x.model)}</span>`:''}<b>${x.confidence??0}% confidence</b></div><p class="tiny">${esc(x.summary||'')}</p>${x.bull_case?researchLists('AI bull case',x.bull_case):''}${x.bear_case?researchLists('AI bear case',x.bear_case):''}`;}catch(e){if(!aiBox.isConnected)return;aiBox.innerHTML=errorBox(e)}}}
async function run(t){let clean=String(t||'').trim().toUpperCase();if(!clean)return;let seq=++researchRequestSeq;lastResearchTicker=clean;$('#ticker').value=clean;$('#out').innerHTML=loading('Loading market structure and timing risk…');let fast=null;try{fast=await api('/api/stock/'+encodeURIComponent(clean));if(seq!==researchRequestSeq)return;$('#out').innerHTML=stockHero(fast)+stockMetrics(fast)+researchPanels(fast,false)+`<div style="margin-top:12px">${loading('Adding SEC, market regime, relative strength and news events in parallel…')}</div>`;mountPriceHistory($('#out .price-history-slot'),fast.ticker||fast.quote?.ticker||clean,fast.history||[],researchChartRange,{indicators:fast.indicators||{},price_model:fast.price_model||{}})}catch(e){if(seq===researchRequestSeq)$('#out').innerHTML=errorBox(e);return}try{let d=await api('/api/research/'+encodeURIComponent(clean),{method:'POST'});if(seq!==researchRequestSeq)return;renderFull(d)}catch(e){if(seq===researchRequestSeq)$('#out').insertAdjacentHTML('beforeend',errorBox(e))}}
$('#researchReturn').onclick=returnFromResearch;$('#search').onsubmit=e=>{e.preventDefault();run($('#ticker').value)};run(lastResearchTicker)}

async function News(){setTitle('News Intelligence','Event-aware current headlines with source reliability, confirmation and duplicate clustering');let v=$('#view'),viewSeq=renderGeneration,newsSeq=0;v.innerHTML=`<div class="section-head"><div><h2>News Search</h2><p>Headlines are grouped into events so syndicated copies do not count as independent confirmation.</p></div><form class="searchbar" id="newsSearch"><input id="newsQuery" value="NVDA" placeholder="NVDA, semiconductors, rates…"><button class="primary">SEARCH NEWS</button></form></div><div id="newsOut"><div class="empty">Enter a ticker, company, sector, or market topic. News only loads when requested.</div></div>`;async function run(q){let seq=++newsSeq;$('#newsOut').innerHTML=loading('Searching and clustering financial news events…');try{let d=await api('/api/news-search/'+encodeURIComponent(q));if(!viewActive(viewSeq)||seq!==newsSeq)return;let tier=d.items.filter(x=>x.reliability>=85).length,confirmed=d.risk.confirmed_event_count??0,total=d.risk.event_count??0;$('#newsOut').innerHTML=`<div class="kpi-row" style="margin-bottom:12px">${metricCard('Query',esc(d.resolved_query))}${metricCard('Event Risk',d.risk.available===false?'UNAVAILABLE':d.risk.score+'/100')}${metricCard('Primary-Source Confirmed',`${confirmed}/${total}`)}${metricCard('Tier-1 Sources',tier)}</div><div class="grid2">${panel('Event Intelligence',newsEventPanel({news_risk:d.risk}),`<span class="caption">${total} grouped events</span>`)}${panel('Headline Feed',newsRows(d.items),`<span class="updated">${esc(d.provider||'Free news')} · ${timeText(d.updated_at)}</span>`)}</div>`}catch(e){if(viewActive(viewSeq)&&seq===newsSeq)$('#newsOut').innerHTML=errorBox(e)}}$('#newsSearch').onsubmit=e=>{e.preventDefault();let q=$('#newsQuery').value.trim();if(q)run(q)}}

async function Portfolio(){setTitle('Portfolio','Editable lots, grouped holdings, thesis health and position-specific protection');let v=$('#view'),viewSeq=renderGeneration,loadSeq=0;let thesisTags=[['revenue_growth','Revenue growth'],['earnings_growth','Earnings growth'],['positive_fcf','Positive FCF'],['uptrend','Healthy uptrend'],['attractive_entry','Attractive entry'],['low_risk','Controlled risk'],['momentum','Strong momentum'],['catalyst','Positive catalyst']];let editingId=null;v.innerHTML=`<form class="panel panel-pad position-form" id="pos"><input id="pt" placeholder="Ticker"><input id="ps" placeholder="Shares" type="number" step="any"><input id="pa" placeholder="Avg price" type="number" step="any"><input class="wide" id="pth" placeholder="Original thesis — why you bought it"><div class="toolbar"><button class="primary" id="savePos">ADD LOT</button><button class="secondary" type="button" id="cancelEdit" hidden>CANCEL EDIT</button></div><div class="thesis-selector wide"><span class="caption">TRACK THESE BUY REASONS</span><div>${thesisTags.map(([id,label])=>`<label><input type="checkbox" value="${id}" class="thesis-tag"> ${label}</label>`).join('')}</div></div></form><div id="out" style="margin-top:12px"></div>`;function reset(){editingId=null;$('#pt').value=$('#ps').value=$('#pa').value=$('#pth').value='';$$('.thesis-tag').forEach(x=>x.checked=false);$('#savePos').textContent='ADD LOT';$('#cancelEdit').hidden=true}$('#cancelEdit').onclick=reset;async function load(){let seq=++loadSeq;try{let r=await api('/api/risk');if(!viewActive(viewSeq)||seq!==loadSeq)return;let grouped=r.grouped?.length?`<section class="panel panel-pad"><div class="panel-title"><h3>Grouped Holdings</h3><span class="caption">Multiple lots combined</span></div><div class="grouped-grid">${r.grouped.map(g=>`<div class="grouped-card"><b>${g.ticker}</b><span>${g.lots} lot(s) · ${number(g.shares)} shares</span><strong>${money(g.value)}</strong><small>Weighted avg ${money(g.avg_cost)} · ${g.pnl_percent==null?'UNAVAILABLE':(g.pnl_percent>=0?'+':'')+g.pnl_percent.toFixed(2)+'%'}</small></div>`).join('')}</div></section>`:'';let sectors=r.sector_exposure?.length?`<section class="panel panel-pad"><div class="panel-title"><h3>Sector Exposure</h3></div><div class="sector-exposure">${r.sector_exposure.map(x=>`<div><span>${esc(x.sector)}</span><div class="bar"><div class="fill" style="width:${Math.min(100,x.percent)}%"></div></div><b>${x.percent}%</b></div>`).join('')}</div></section>`:'';let missingBanner=r.valuation_complete?'':`<div class="warning-box">${r.unpriced_lots} lot(s) have unavailable prices. Portfolio totals, P/L, concentration and sector exposure cannot be calculated reliably. Priced subset: ${money(r.priced_market_value)} market value against ${money(r.priced_cost)} cost.</div>`;$('#out').innerHTML=`${missingBanner}<div class="portfolio-summary">${metricCard('Market Value',money(r.total_value))}${metricCard('Cost Basis',money(r.total_cost))}${metricCard('Unrealized P/L',money(r.total_pnl),r.total_pnl_percent!=null?`${r.total_pnl_percent>=0?'+':''}${r.total_pnl_percent.toFixed(2)}%`:'')}${metricCard('Lots',r.positions.length)}${metricCard('Highest Exit Risk',r.positions.length?(r.valuation_complete?Math.max(...r.positions.map(x=>x.exit_risk?.score||0))+'/100':'UNAVAILABLE'):'—')}</div>${(r.warnings||[]).map(w=>`<div class="warning-box">${esc(w.type)}: <b>${esc(w.ticker)}</b> is ${w.percent}% of current portfolio value.</div>`).join('')}<div class="grid2">${grouped}${sectors}</div>${r.positions.length?`<div class="table-wrap"><table><thead><tr><th>Lot</th><th>Sector</th><th>Price / P&L</th><th>Exit Risk</th><th>Thesis Health</th><th>Position Action</th><th>Trailing Exit</th><th>Protection</th><th>Thesis</th><th>Actions</th></tr></thead><tbody>${r.positions.map(p=>`<tr><td><b>${p.ticker}</b><span class="company">${p.shares} sh · avg ${money(p.avg_price)}</span></td><td>${esc(p.sector||'Broad Market')}</td><td>${p.error?'—':`${money(p.price)}<span class="company">${pct(p.pnl_percent)}</span>`}</td><td>${p.error?'<span class="bad">ERROR</span>':`<span class="status ${statusClass(p.exit_risk?.label)}">${p.exit_risk?.score}/100 ${p.exit_risk?.label}</span>`}</td><td>${p.thesis_health?.tracked?`<b class="${(p.thesis_health.score??0)>=70?'good':(p.thesis_health.score??0)<45?'bad':'warn'}">${p.thesis_health.score??'—'}/100</b><span class="company">${p.thesis_health.valid} valid / ${p.thesis_health.invalid} broken</span>`:'<span class="company">Not tracked</span>'}</td><td><span class="status ${statusClass(p.position_strategy?.action||'')}">${esc(p.position_strategy?.action||'—')}</span>${p.position_strategy?.partial_profit_percent?`<span class="company">Partial: ${p.position_strategy.partial_profit_percent}%</span>`:''}</td><td>${money(p.position_strategy?.trailing_exit)}</td><td>${p.position_strategy?.protected_gain_percent>0?`+${p.position_strategy.protected_gain_percent}% above cost`:'—'}</td><td><span class="company">${esc(p.thesis||'—')}</span></td><td><div class="row-actions"><button class="secondary small" data-edit="${p.id}">EDIT</button><button class="danger-btn" data-del="${p.id}">REMOVE</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No positions stored yet.</div>'}`;$$('[data-del]').forEach(b=>b.onclick=async()=>{await api('/api/positions/'+b.dataset.del,{method:'DELETE'});if(!viewActive(viewSeq))return;if(editingId===Number(b.dataset.del))reset();load()});$$('[data-edit]').forEach(b=>b.onclick=()=>{let pos=r.positions.find(x=>x.id===Number(b.dataset.edit));if(!pos)return;editingId=pos.id;$('#pt').value=pos.ticker;$('#ps').value=pos.shares;$('#pa').value=pos.avg_price;$('#pth').value=pos.thesis||'';let tags=[];try{tags=Array.isArray(pos.thesis_tags)?pos.thesis_tags:JSON.parse(pos.thesis_json||'[]')}catch{}$$('.thesis-tag').forEach(x=>x.checked=tags.includes(x.value));$('#savePos').textContent='SAVE CHANGES';$('#cancelEdit').hidden=false;window.scrollTo({top:0,behavior:'smooth'})})}catch(e){if(viewActive(viewSeq)&&seq===loadSeq)$('#out').innerHTML=errorBox(e)}}$('#pos').onsubmit=async e=>{e.preventDefault();try{let tags=$$('.thesis-tag:checked').map(x=>x.value),body=JSON.stringify({ticker:$('#pt').value,shares:Number($('#ps').value),avg_price:Number($('#pa').value),thesis:$('#pth').value,thesis_tags:tags});if(editingId)await api('/api/positions/'+editingId,{method:'PUT',body});else await api('/api/positions',{method:'POST',body});if(!viewActive(viewSeq))return;reset();load()}catch(x){if(viewActive(viewSeq))$('#out').insertAdjacentHTML('afterbegin',errorBox(x))}};load()}

async function Risk(){setTitle('Risk Monitor','Exit defense, thesis damage and profit protection for every saved position');let v=$('#view'),viewSeq=renderGeneration,riskSeq=0;v.innerHTML=`<div class="section-head"><div><h2>Portfolio Risk Defense</h2><p>News events, market risk, technical damage, thesis health and your cost basis are evaluated together.</p></div><button class="primary" id="scanRisk">SCAN PORTFOLIO</button></div><div id="out"></div>`;async function run(){let seq=++riskSeq;let b=$('#scanRisk');b.disabled=true;$('#out').innerHTML=loading('Checking portfolio evidence, thesis health and profit protection…');try{let d=await api('/api/risk');if(!viewActive(viewSeq)||seq!==riskSeq)return;$('#out').innerHTML=(d.positions.length&&!d.valuation_complete?`<div class="warning-box">RISK SCAN INCOMPLETE: ${d.unpriced_lots??0} lot(s) could not be priced. Current P/L, exposure, and exit assessments for those lots are unavailable.</div>`:'')+(d.warnings||[]).map(w=>`<div class="warning-box">${esc(w.type)}: <b>${esc(w.ticker)}</b> is ${w.percent}% of portfolio value.</div>`).join('')+(d.positions.length?`<div class="risk-cards">${d.positions.map(p=>`<section class="panel risk-card"><div class="risk-head"><div><b>${p.ticker}</b><div class="tiny">${esc(p.thesis||'No stored thesis')}</div></div><span class="status ${statusClass(p.exit_risk?.label)}">${esc(p.exit_risk?.label||'ERROR')}</span></div>${p.error?errorBox(p.error):`<div class="position-decision"><div><span class="caption">POSITION ACTION</span><b>${esc(p.position_strategy?.action||'—')}</b>${p.position_strategy?.partial_profit_percent?`<small>Consider partial profit: ${p.position_strategy.partial_profit_percent}%</small>`:''}</div><div><span class="caption">EXIT RISK</span><b class="${clsRisk(p.exit_risk?.score||0)}">${p.exit_risk?.score??0}/100</b></div></div><div class="fund-grid" style="margin-top:9px">${fundCard('Current',money(p.price))}${fundCard('P/L',p.pnl_percent!=null?pct(p.pnl_percent):'—')}${fundCard('Trailing Exit',money(p.position_strategy?.trailing_exit))}${fundCard('Protected Gain',p.position_strategy?.protected_gain_percent>0?`+${p.position_strategy.protected_gain_percent}%`:'—')}${fundCard('Thesis Health',p.thesis_health?.tracked?(p.thesis_health.score??'—')+'/100':'Not tracked')}${fundCard('News Risk',p.news_risk?.available===false?'UNAVAILABLE':(p.news_risk?.score??0))}${fundCard('Model Risk Exit',money(p.price_model?.risk_exit))}${fundCard('Take Profit',rangeText(p.price_model?.take_profit_zone))}</div>${p.thesis_health?.tracked?`<div class="thesis-checks compact-checks" style="margin-top:9px">${(p.thesis_health.items||[]).map(x=>`<div class="thesis-check ${x.valid===true?'ok':x.valid===false?'broken':'unknown'}"><span>${x.valid===true?'✓':x.valid===false?'✕':'?'}</span><div><b>${esc(x.label)}</b><small>${esc(x.detail)}</small></div></div>`).join('')}</div>`:''}${p.top_risk_news?.length?`<div class="list-box" style="margin-top:9px"><h4>Top risk headlines</h4><ul class="thesis-list">${p.top_risk_news.map(x=>`<li>${esc(x.title)}</li>`).join('')}</ul></div>`:''}`}</section>`).join('')}</div>`:'<div class="empty">Add positions in Portfolio first.</div>')}catch(e){if(viewActive(viewSeq)&&seq===riskSeq)$('#out').innerHTML=errorBox(e)}finally{b.disabled=false}}$('#scanRisk').onclick=run;run()}

async function Alerts(){setTitle('Alerts','Positions that currently require attention');let v=$('#view'),viewSeq=renderGeneration;v.innerHTML=loading('Building current alert queue…');try{let d=await api('/api/alerts');if(!viewActive(viewSeq))return;v.innerHTML=`<div class="section-head"><div><h2>Risk Alert Queue</h2><p>Only positions at WATCH or above appear here.</p></div><span class="badge ${d.count?'warn':'good'}">${d.count} ACTIVE</span></div>${d.alerts.length?`<section class="panel">${d.alerts.map(a=>`<div class="alert-row"><span class="alert-sev">${esc(a.severity)}</span><div><div class="alert-title"><b>${esc(a.ticker)}</b> · ${esc(a.title)}</div><div class="alert-body">${esc(a.body)}</div></div><b class="${clsRisk(a.risk_score||0)}">${a.risk_score??'—'}</b></div>`).join('')}</section>`:'<div class="empty">No WATCH-or-higher portfolio alerts at this time.</div>'}<p class="updated" style="margin-top:8px">Updated ${timeText(d.updated_at)}</p>`}catch(e){if(viewActive(viewSeq))v.innerHTML=errorBox(e)}}

async function Settings(){setTitle('Settings','Data, scanner and optional local-AI configuration');let v=$('#view'),viewSeq=renderGeneration;v.innerHTML=loading('Loading settings…');try{let s=await api('/api/settings');if(!viewActive(viewSeq))return;v.innerHTML=`<form id="settingsForm"><div class="settings-layout"><section class="panel setting-group"><h3>Core Research</h3><p>Always active. Deterministic calculations do not depend on AI.</p><div class="toggle-row"><div><b>Core engine</b><div class="tiny">Hunter, timing-aware scoring, SEC, news risk, entry/exit, portfolio defense</div></div><span class="badge good">ACTIVE</span></div><label>Hunter max symbols<input id="hm" type="number" min="5" max="100" value="${s.hunter_max_symbols}"></label><label>Custom Hunter universe<textarea id="hu" placeholder="Blank = built-in universe. Otherwise comma-separated tickers.">${esc(s.hunter_universe||'')}</textarea></label></section><section class="panel setting-group"><h3>Optional Ollama</h3><p>Adds narrative interpretation only. Core decisions remain available when this is off.</p><label>AI enhancement<select id="oe"><option value="false">OFF — Core Research only</option><option value="true">ON — Add Ollama interpretation</option></select></label><label>Ollama URL<input id="ou" value="${esc(s.ollama_url)}"></label><label>Ollama model<select id="om"><option value="auto">auto</option>${s.ollama_model&&s.ollama_model!=='auto'?`<option value="${esc(s.ollama_model)}">${esc(s.ollama_model)}</option>`:''}</select></label><div class="toolbar"><button class="secondary" type="button" id="testOllama">TEST / LOAD MODELS</button><span id="ollamaStatus" class="tiny"></span></div></section><section class="panel setting-group"><h3>SEC Access</h3><p>SEC automated access expects an identifying User-Agent.</p><label>SEC User-Agent<input id="su" value="${esc(s.sec_user_agent)}"><small>Recommended format: StonkResearch/0.5 your-email@example.com</small></label><div class="toggle-row"><div><b>Primary-source verification</b><div class="tiny">10-K, 10-Q, 8-K and XBRL company facts</div></div><span class="badge good">ENABLED</span></div></section><section class="panel setting-group"><h3>Data Policy</h3><p>This build intentionally remains $0 and zero-dependency.</p><div class="toggle-row"><div><b>Market data</b><div class="tiny">Free best-effort Yahoo chart endpoint</div></div><span class="badge warn">NOT REAL-TIME GRADE</span></div><div class="toggle-row"><div><b>News discovery</b><div class="tiny">Yahoo Finance news + GDELT fallback + duplicate-resistant risk scoring</div></div><span class="badge good">FREE</span></div><div class="toggle-row"><div><b>Automatic trading</b><div class="tiny">Never enabled by this application</div></div><span class="badge">DISABLED</span></div></section><section class="panel setting-group update-settings"><h3>Application Updates</h3><p>Checks the latest reviewed code merged into GitHub main. Updates only after you approve them. Your portfolio and settings remain on this computer.</p><div class="tiny" id="updateStatus">Checking updater status…</div><div class="tiny" id="updateDetails"></div><progress id="updateProgress" max="100" value="0" style="display:none;width:100%;margin-top:8px"></progress><div class="toolbar" style="margin-top:12px"><button class="secondary" type="button" id="checkUpdates">CHECK FOR UPDATES</button><button class="primary" type="button" id="downloadUpdate" style="display:none">DOWNLOAD &amp; VERIFY</button><button class="primary" type="button" id="applyUpdate" style="display:none">RESTART TO INSTALL</button></div><p class="tiny" style="margin-top:9px">Private GitHub repository: install the free GitHub CLI and run gh auth login once. The app never stores a token.</p><p class="tiny" id="previousUpdateResult"></p></section></div><div class="toolbar" style="margin-top:12px"><button class="primary" type="submit">SAVE SETTINGS</button><span id="saved" class="saved"></span></div><div id="settingsErr"></div></form>`;bindUpdateControls();refreshUpdateState();$('#oe').value=String(s.ollama_enabled);$('#om').value=s.ollama_model||'auto';$('#testOllama').onclick=async()=>{let b=$('#testOllama'),st=$('#ollamaStatus');b.disabled=true;st.textContent='Checking…';try{let d=await api('/api/ollama/status');if(!viewActive(viewSeq))return;let sel=$('#om'),cur=sel.value;sel.innerHTML='<option value="auto">auto</option>'+(d.models||[]).map(m=>`<option value="${esc(m)}">${esc(m)}</option>`).join('');if([...sel.options].some(o=>o.value===cur))sel.value=cur;st.textContent=d.available?`Connected · ${d.models.length} model(s)`:'Not reachable / no local models';st.className=d.available?'tiny good':'tiny warn'}catch(e){st.textContent=e.message;st.className='tiny bad'}finally{b.disabled=false}};$('#settingsForm').onsubmit=async e=>{e.preventDefault();$('#saved').textContent='Saving…';$('#settingsErr').innerHTML='';try{let out=await api('/api/settings',{method:'POST',body:JSON.stringify({ollama_enabled:$('#oe').value==='true',ollama_url:$('#ou').value.trim(),ollama_model:$('#om').value,sec_user_agent:$('#su').value.trim(),hunter_max_symbols:Number($('#hm').value),hunter_universe:$('#hu').value.trim()})});if(!viewActive(viewSeq))return;$('#hm').value=out.hunter_max_symbols;$('#oe').value=String(out.ollama_enabled);$('#saved').textContent='Saved ✓';setTimeout(()=>{if($('#saved'))$('#saved').textContent=''},1800)}catch(x){if(!viewActive(viewSeq))return;$('#saved').textContent='';$('#settingsErr').innerHTML=errorBox(x)}}}catch(e){if(viewActive(viewSeq))v.innerHTML=errorBox(e)}}
function render(auto=false){++renderGeneration;if(page==='Market')Market();else if(page==='Stonk Hunter')Hunter(auto);else if(page==='Deep Research')DeepResearch();else if(page==='News Intelligence')News();else if(page==='Portfolio')Portfolio();else if(page==='Risk Monitor')Risk();else if(page==='Alerts')Alerts();else if(page==='Settings')Settings()}
function heartbeat(){fetch('/api/ping',{cache:'no-store'}).catch(()=>{})}
shell();$('#globalSearch').onsubmit=e=>{e.preventDefault();let t=$('#globalTicker').value.trim().toUpperCase();if(!t)return;openResearchTicker(t,page)};document.addEventListener('keydown',e=>{let tag=document.activeElement?.tagName;if(e.key==='Escape'&&page==='Deep Research'&&researchDetailActive&&!['INPUT','TEXTAREA','SELECT'].includes(tag))returnFromResearch()});heartbeat();setInterval(heartbeat,4000);render();startUpdateChecks();
